contracts/ArcMultiSigFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./ArcMultiSigWallet.sol";

/**
 * @title ArcMultiSigFactory
 * @notice Factory contract for deploying ArcMultiSigWallet instances
 */
contract ArcMultiSigFactory {
    // Events
    event WalletCreated(
        address indexed wallet,
        address indexed creator,
        address[] signers,
        uint256 requiredSignatures
    );

    // State
    address[] public deployedWallets;
    mapping(address => address[]) public userWallets;
    mapping(address => bool) public isDeployedWallet;

    /**
     * @notice Create a new multi-sig wallet
     * @param _signers List of initial signers
     * @param _requiredSignatures Number of required signatures (threshold)
     * @return wallet Address of the new wallet
     */
    function createWallet(
        address[] calldata _signers,
        uint256 _requiredSignatures
    ) external returns (address wallet) {
        ArcMultiSigWallet newWallet = new ArcMultiSigWallet(
            _signers,
            _requiredSignatures
        );

        wallet = address(newWallet);
        deployedWallets.push(wallet);
        isDeployedWallet[wallet] = true;

        // Track wallet for each signer
        for (uint256 i = 0; i < _signers.length; i++) {
            userWallets[_signers[i]].push(wallet);
        }

        emit WalletCreated(wallet, msg.sender, _signers, _requiredSignatures);

        return wallet;
    }

    /**
     * @notice Create wallet with deterministic address using CREATE2
     * @param _signers List of initial signers
     * @param _requiredSignatures Number of required signatures
     * @param _salt Salt for deterministic address
     * @return wallet Address of the new wallet
     */
    function createWalletDeterministic(
        address[] calldata _signers,
        uint256 _requiredSignatures,
        bytes32 _salt
    ) external returns (address wallet) {
        bytes memory bytecode = abi.encodePacked(
            type(ArcMultiSigWallet).creationCode,
            abi.encode(_signers, _requiredSignatures)
        );

        assembly {
            wallet := create2(0, add(bytecode, 0x20), mload(bytecode), _salt)
        }

        require(wallet != address(0), "Deployment failed");

        deployedWallets.push(wallet);
        isDeployedWallet[wallet] = true;

        // Track wallet for each signer
        for (uint256 i = 0; i < _signers.length; i++) {
            userWallets[_signers[i]].push(wallet);
        }

        emit WalletCreated(wallet, msg.sender, _signers, _requiredSignatures);

        return wallet;
    }

    /**
     * @notice Compute deterministic wallet address
     * @param _signers List of initial signers
     * @param _requiredSignatures Number of required signatures
     * @param _salt Salt for deterministic address
     * @return predicted Predicted wallet address
     */
    function computeWalletAddress(
        address[] calldata _signers,
        uint256 _requiredSignatures,
        bytes32 _salt
    ) external view returns (address predicted) {
        bytes memory bytecode = abi.encodePacked(
            type(ArcMultiSigWallet).creationCode,
            abi.encode(_signers, _requiredSignatures)
        );

        bytes32 hash = keccak256(
            abi.encodePacked(
                bytes1(0xff),
                address(this),
                _salt,
                keccak256(bytecode)
            )
        );

        return address(uint160(uint256(hash)));
    }

    /**
     * @notice Get total number of deployed wallets
     */
    function getDeployedWalletsCount() external view returns (uint256) {
        return deployedWallets.length;
    }

    /**
     * @notice Get all deployed wallets
     */
    function getDeployedWallets() external view returns (address[] memory) {
        return deployedWallets;
    }

    /**
     * @notice Get wallets for a specific user
     * @param _user User address
     */
    function getUserWallets(address _user) external view returns (address[] memory) {
        return userWallets[_user];
    }

    /**
     * @notice Get deployed wallets with pagination
     * @param _offset Start index
     * @param _limit Max number of results
     */
    function getDeployedWalletsPaginated(
        uint256 _offset,
        uint256 _limit
    ) external view returns (address[] memory) {
        if (_offset >= deployedWallets.length) {
            return new address[](0);
        }

        uint256 end = _offset + _limit;
        if (end > deployedWallets.length) {
            end = deployedWallets.length;
        }

        address[] memory result = new address[](end - _offset);
        for (uint256 i = _offset; i < end; i++) {
            result[i - _offset] = deployedWallets[i];
        }

        return result;
    }
}

contracts/ArcMultiSigWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title ArcMultiSigWallet
 * @notice Multi-signature wallet with configurable threshold and 24-hour expiration
 */
contract ArcMultiSigWallet is ReentrancyGuard {
    using SafeERC20 for IERC20;

    // Events
    event Deposit(address indexed sender, uint256 amount);
    event TransactionSubmitted(uint256 indexed txId, address indexed submitter, address indexed to, uint256 value, address token);
    event TransactionApproved(uint256 indexed txId, address indexed approver);
    event TransactionRejected(uint256 indexed txId, address indexed rejector);
    event TransactionExecuted(uint256 indexed txId);
    event TransactionExpired(uint256 indexed txId);
    event SignerAdded(address indexed signer);
    event SignerRemoved(address indexed signer);
    event ThresholdChanged(uint256 oldThreshold, uint256 newThreshold);

    // Transaction struct
    struct Transaction {
        address to;
        uint256 value;
        address token; // address(0) for native ETH
        bytes data;
        bool executed;
        uint256 approvalCount;
        uint256 rejectionCount;
        uint256 createdAt;
        uint256 expiresAt;
    }

    // State variables
    address[] public signers;
    mapping(address => bool) public isSigner;
    uint256 public requiredSignatures;

    Transaction[] public transactions;
    mapping(uint256 => mapping(address => bool)) public hasApproved;
    mapping(uint256 => mapping(address => bool)) public hasRejected;

    // Constants
    uint256 public constant EXPIRATION_TIME = 24 hours;

    // Modifiers
    modifier onlySigner() {
        require(isSigner[msg.sender], "Not a signer");
        _;
    }

    modifier onlyWallet() {
        require(msg.sender == address(this), "Only wallet can call");
        _;
    }

    modifier txExists(uint256 _txId) {
        require(_txId < transactions.length, "Transaction does not exist");
        _;
    }

    modifier notExecuted(uint256 _txId) {
        require(!transactions[_txId].executed, "Transaction already executed");
        _;
    }

    modifier notExpired(uint256 _txId) {
        require(block.timestamp <= transactions[_txId].expiresAt, "Transaction expired");
        _;
    }

    /**
     * @notice Initialize the multi-sig wallet
     * @param _signers Initial list of signers
     * @param _requiredSignatures Number of required signatures (threshold)
     */
    constructor(address[] memory _signers, uint256 _requiredSignatures) {
        require(_signers.length > 0, "Signers required");
        require(
            _requiredSignatures > 0 && _requiredSignatures <= _signers.length,
            "Invalid threshold"
        );

        for (uint256 i = 0; i < _signers.length; i++) {
            address signer = _signers[i];
            require(signer != address(0), "Invalid signer");
            require(!isSigner[signer], "Duplicate signer");

            isSigner[signer] = true;
            signers.push(signer);
        }

        requiredSignatures = _requiredSignatures;
    }

    /**
     * @notice Receive native ETH
     */
    receive() external payable {
        emit Deposit(msg.sender, msg.value);
    }

    /**
     * @notice Submit a new transaction
     * @param _to Target address
     * @param _value Amount of ETH (0 for token transfers)
     * @param _token Token address (address(0) for ETH)
     * @param _data Call data
     * @return txId Transaction ID
     */
    function submitTransaction(
        address _to,
        uint256 _value,
        address _token,
        bytes calldata _data
    ) external onlySigner returns (uint256 txId) {
        require(_to != address(0), "Invalid target");

        txId = transactions.length;

        transactions.push(Transaction({
            to: _to,
            value: _value,
            token: _token,
            data: _data,
            executed: false,
            approvalCount: 1, // Submitter auto-approves
            rejectionCount: 0,
            createdAt: block.timestamp,
            expiresAt: block.timestamp + EXPIRATION_TIME
        }));

        hasApproved[txId][msg.sender] = true;

        emit TransactionSubmitted(txId, msg.sender, _to, _value, _token);
        emit TransactionApproved(txId, msg.sender);

        // Auto-execute if threshold is 1
        if (requiredSignatures == 1) {
            _executeTransaction(txId);
        }

        return txId;
    }

    /**
     * @notice Approve a pending transaction
     * @param _txId Transaction ID
     */
    function approveTransaction(uint256 _txId)
        external
        onlySigner
        txExists(_txId)
        notExecuted(_txId)
        notExpired(_txId)
    {
        require(!hasApproved[_txId][msg.sender], "Already approved");
        require(!hasRejected[_txId][msg.sender], "Already rejected");

        hasApproved[_txId][msg.sender] = true;
        transactions[_txId].approvalCount++;

        emit TransactionApproved(_txId, msg.sender);

        // Execute if threshold reached
        if (transactions[_txId].approvalCount >= requiredSignatures) {
            _executeTransaction(_txId);
        }
    }

    /**
     * @notice Reject a pending transaction
     * @param _txId Transaction ID
     */
    function rejectTransaction(uint256 _txId)
        external
        onlySigner
        txExists(_txId)
        notExecuted(_txId)
        notExpired(_txId)
    {
        require(!hasApproved[_txId][msg.sender], "Already approved");
        require(!hasRejected[_txId][msg.sender], "Already rejected");

        hasRejected[_txId][msg.sender] = true;
        transactions[_txId].rejectionCount++;

        emit TransactionRejected(_txId, msg.sender);
    }

    /**
     * @notice Execute a transaction that has enough approvals
     * @param _txId Transaction ID
     */
    function executeTransaction(uint256 _txId)
        external
        onlySigner
        txExists(_txId)
        notExecuted(_txId)
        notExpired(_txId)
    {
        require(
            transactions[_txId].approvalCount >= requiredSignatures,
            "Not enough approvals"
        );

        _executeTransaction(_txId);
    }

    /**
     * @notice Internal function to execute transaction
     */
    function _executeTransaction(uint256 _txId) internal nonReentrant {
        Transaction storage txn = transactions[_txId];
        txn.executed = true;

        if (txn.token == address(0)) {
            // Native ETH transfer
            (bool success, ) = txn.to.call{value: txn.value}(txn.data);
            require(success, "ETH transfer failed");
        } else {
            // ERC20 token transfer
            if (txn.data.length == 0) {
                // Simple transfer
                IERC20(txn.token).safeTransfer(txn.to, txn.value);
            } else {
                // Custom call (e.g., approve, transferFrom)
                (bool success, ) = txn.token.call(txn.data);
                require(success, "Token call failed");
            }
        }

        emit TransactionExecuted(_txId);
    }

    /**
     * @notice Add a new signer (requires multi-sig approval)
     * @param _signer Address of new signer
     */
    function addSigner(address _signer) external onlyWallet {
        require(_signer != address(0), "Invalid signer");
        require(!isSigner[_signer], "Already a signer");

        isSigner[_signer] = true;
        signers.push(_signer);

        emit SignerAdded(_signer);
    }

    /**
     * @notice Remove a signer (requires multi-sig approval)
     * @param _signer Address of signer to remove
     */
    function removeSigner(address _signer) external onlyWallet {
        require(isSigner[_signer], "Not a signer");
        require(signers.length - 1 >= requiredSignatures, "Cannot reduce below threshold");
        require(signers.length > 1, "Cannot remove last signer");

        isSigner[_signer] = false;

        // Remove from signers array
        for (uint256 i = 0; i < signers.length; i++) {
            if (signers[i] == _signer) {
                signers[i] = signers[signers.length - 1];
                signers.pop();
                break;
            }
        }

        emit SignerRemoved(_signer);
    }

    /**
     * @notice Change the required signatures threshold (requires multi-sig approval)
     * @param _newThreshold New threshold value
     */
    function changeThreshold(uint256 _newThreshold) external onlyWallet {
        require(_newThreshold > 0, "Invalid threshold");
        require(_newThreshold <= signers.length, "Threshold exceeds signers");

        uint256 oldThreshold = requiredSignatures;
        requiredSignatures = _newThreshold;

        emit ThresholdChanged(oldThreshold, _newThreshold);
    }

    // View functions

    /**
     * @notice Get the number of signers
     */
    function getSignerCount() external view returns (uint256) {
        return signers.length;
    }

    /**
     * @notice Get all signers
     */
    function getSigners() external view returns (address[] memory) {
        return signers;
    }

    /**
     * @notice Get transaction count
     */
    function getTransactionCount() external view returns (uint256) {
        return transactions.length;
    }

    /**
     * @notice Get transaction details
     */
    function getTransaction(uint256 _txId)
        external
        view
        returns (
            address to,
            uint256 value,
            address token,
            bytes memory data,
            bool executed,
            uint256 approvalCount,
            uint256 rejectionCount,
            uint256 createdAt,
            uint256 expiresAt
        )
    {
        Transaction storage txn = transactions[_txId];
        return (
            txn.to,
            txn.value,
            txn.token,
            txn.data,
            txn.executed,
            txn.approvalCount,
            txn.rejectionCount,
            txn.createdAt,
            txn.expiresAt
        );
    }

    /**
     * @notice Check if a transaction is expired
     */
    function isExpired(uint256 _txId) external view returns (bool) {
        return block.timestamp > transactions[_txId].expiresAt;
    }

    /**
     * @notice Get pending transactions
     */
    function getPendingTransactions() external view returns (uint256[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < transactions.length; i++) {
            if (!transactions[i].executed && block.timestamp <= transactions[i].expiresAt) {
                count++;
            }
        }

        uint256[] memory pending = new uint256[](count);
        uint256 index = 0;
        for (uint256 i = 0; i < transactions.length; i++) {
            if (!transactions[i].executed && block.timestamp <= transactions[i].expiresAt) {
                pending[index] = i;
                index++;
            }
        }

        return pending;
    }

    /**
     * @notice Get token balance
     * @param _token Token address (address(0) for ETH)
     */
    function getBalance(address _token) external view returns (uint256) {
        if (_token == address(0)) {
            return address(this).balance;
        }
        return IERC20(_token).balanceOf(address(this));
    }
}

contracts/ArcPaymaster.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IEntryPoint} from "./IEntryPoint.sol";

/**
 * @title ArcPaymaster
 * @notice ERC-4337 Paymaster implementation for sponsoring gas fees
 * @dev Supports multiple sponsorship strategies: whitelist, budget, rate limiting
 */
contract ArcPaymaster {
    error OnlyOwner();
    error OnlyEntryPoint();
    error InsufficientDeposit();
    error NotWhitelisted();
    error RateLimitExceeded();
    error BudgetExceeded();
    error InvalidPolicy();
    error WithdrawFailed();

    event Deposited(address indexed sender, uint256 amount);
    event Withdrawn(address indexed to, uint256 amount);
    event StakeAdded(uint256 amount, uint32 unstakeDelaySec);
    event PolicyUpdated(string policyType, bool enabled);
    event WhitelistUpdated(address indexed account, bool enabled);
    event UserOpSponsored(address indexed sender, uint256 actualGasCost);

    IEntryPoint public immutable entryPoint;
    address public owner;

    // Policy configuration
    struct PaymasterConfig {
        bool whitelistEnabled;
        bool budgetEnabled;
        bool rateLimitEnabled;
        uint256 maxCostPerOp;      // Maximum gas cost per operation (in wei)
        uint256 dailyBudget;        // Maximum spending per day (in wei)
        uint256 maxOpsPerHour;      // Maximum operations per hour per address
    }

    PaymasterConfig public config;

    // Whitelist for addresses that can receive sponsorship
    mapping(address => bool) public whitelist;

    // Rate limiting: track operations per address
    mapping(address => uint256) public lastOpTimestamp;
    mapping(address => uint256) public opsCountInHour;

    // Budget tracking
    uint256 public dailySpent;
    uint256 public lastResetTimestamp;

    // Statistics
    uint256 public totalSponsored;
    uint256 public totalCost;

    modifier onlyOwner() {
        if (msg.sender != owner) revert OnlyOwner();
        _;
    }

    modifier onlyEntryPoint() {
        if (msg.sender != address(entryPoint)) revert OnlyEntryPoint();
        _;
    }

    constructor(address _entryPoint, address _owner) {
        require(_entryPoint != address(0), "Invalid EntryPoint");
        require(_owner != address(0), "Invalid owner");

        entryPoint = IEntryPoint(_entryPoint);
        owner = _owner;
        lastResetTimestamp = block.timestamp;

        // Default configuration: whitelist mode enabled
        config = PaymasterConfig({
            whitelistEnabled: true,
            budgetEnabled: false,
            rateLimitEnabled: false,
            maxCostPerOp: 0.01 ether,
            dailyBudget: 1 ether,
            maxOpsPerHour: 10
        });
    }

    // ============================================================================
    // ERC-4337 Paymaster Interface
    // ============================================================================

    /**
     * @notice Validate a UserOperation and determine if paymaster will sponsor it
     * @param userOp The UserOperation to validate
     * @param userOpHash Hash of the UserOperation
     * @param maxCost Maximum gas cost for this operation
     * @return context Data to pass to postOp (empty if no postOp needed)
     * @return validationData Validation result (0 = success)
     */
    function validatePaymasterUserOp(
        IEntryPoint.UserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 maxCost
    ) external onlyEntryPoint returns (bytes memory context, uint256 validationData) {
        // Check if paymaster has enough deposit
        uint256 balance = entryPoint.balanceOf(address(this));
        if (balance < maxCost) revert InsufficientDeposit();

        // Apply policies
        _checkPolicies(userOp.sender, maxCost);

        // Reset daily budget if needed
        _resetDailyBudgetIfNeeded();

        // Update rate limiting
        if (config.rateLimitEnabled) {
            _updateRateLimit(userOp.sender);
        }

        // Update budget tracking
        if (config.budgetEnabled) {
            dailySpent += maxCost;
        }

        // Encode context for postOp
        context = abi.encode(userOp.sender, maxCost);

        // Return success (validationData = 0)
        return (context, 0);
    }

    /**
     * @notice Post-operation handler called after UserOperation execution
     * @param mode Whether the operation succeeded or reverted
     * @param context Data from validatePaymasterUserOp
     * @param actualGasCost Actual gas cost of the operation
     */
    function postOp(
        IEntryPoint.PostOpMode mode,
        bytes calldata context,
        uint256 actualGasCost,
        uint256 /* actualUserOpFeePerGas */
    ) external onlyEntryPoint {
        (address sender, uint256 maxCost) = abi.decode(context, (address, uint256));

        // Update statistics
        totalSponsored++;
        totalCost += actualGasCost;

        // Adjust daily spent (refund unused gas)
        if (config.budgetEnabled && maxCost > actualGasCost) {
            dailySpent -= (maxCost - actualGasCost);
        }

        emit UserOpSponsored(sender, actualGasCost);

        // Note: In advanced implementations, this is where you would:
        // 1. Pull ERC-20 tokens from user (token-based payment)
        // 2. Swap tokens for ETH
        // 3. Handle refunds
    }

    // ============================================================================
    // Policy Management
    // ============================================================================

    function _checkPolicies(address sender, uint256 estimatedCost) internal view {
        // Check whitelist
        if (config.whitelistEnabled && !whitelist[sender]) {
            revert NotWhitelisted();
        }

        // Check budget
        if (config.budgetEnabled) {
            if (estimatedCost > config.maxCostPerOp) {
                revert BudgetExceeded();
            }
            if (dailySpent + estimatedCost > config.dailyBudget) {
                revert BudgetExceeded();
            }
        }

        // Check rate limit
        if (config.rateLimitEnabled) {
            uint256 hoursSinceLastOp = (block.timestamp - lastOpTimestamp[sender]) / 3600;

            // Reset counter if more than 1 hour has passed
            if (hoursSinceLastOp >= 1) {
                // Counter will be reset in _updateRateLimit
            } else if (opsCountInHour[sender] >= config.maxOpsPerHour) {
                revert RateLimitExceeded();
            }
        }
    }

    function _updateRateLimit(address sender) internal {
        uint256 hoursSinceLastOp = (block.timestamp - lastOpTimestamp[sender]) / 3600;

        if (hoursSinceLastOp >= 1) {
            // Reset counter
            opsCountInHour[sender] = 1;
        } else {
            // Increment counter
            opsCountInHour[sender]++;
        }

        lastOpTimestamp[sender] = block.timestamp;
    }

    function _resetDailyBudgetIfNeeded() internal {
        uint256 daysSinceReset = (block.timestamp - lastResetTimestamp) / 86400;

        if (daysSinceReset >= 1) {
            dailySpent = 0;
            lastResetTimestamp = block.timestamp;
        }
    }

    // ============================================================================
    // Owner Functions
    // ============================================================================

    /**
     * @notice Update policy configuration
     */
    function setWhitelistPolicy(bool enabled) external onlyOwner {
        config.whitelistEnabled = enabled;
        emit PolicyUpdated("whitelist", enabled);
    }

    function setBudgetPolicy(
        bool enabled,
        uint256 maxCostPerOp,
        uint256 dailyBudget
    ) external onlyOwner {
        if (enabled && (maxCostPerOp == 0 || dailyBudget == 0)) {
            revert InvalidPolicy();
        }

        config.budgetEnabled = enabled;
        config.maxCostPerOp = maxCostPerOp;
        config.dailyBudget = dailyBudget;

        emit PolicyUpdated("budget", enabled);
    }

    function setRateLimitPolicy(bool enabled, uint256 maxOpsPerHour) external onlyOwner {
        if (enabled && maxOpsPerHour == 0) {
            revert InvalidPolicy();
        }

        config.rateLimitEnabled = enabled;
        config.maxOpsPerHour = maxOpsPerHour;

        emit PolicyUpdated("rateLimit", enabled);
    }

    /**
     * @notice Add or remove addresses from whitelist
     */
    function setWhitelist(address[] calldata addresses, bool enabled) external onlyOwner {
        for (uint256 i = 0; i < addresses.length; i++) {
            whitelist[addresses[i]] = enabled;
            emit WhitelistUpdated(addresses[i], enabled);
        }
    }

    /**
     * @notice Transfer ownership
     */
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Invalid owner");
        owner = newOwner;
    }

    // ============================================================================
    // Deposit Management
    // ============================================================================

    /**
     * @notice Deposit ETH to paymaster's EntryPoint balance
     */
    function deposit() external payable {
        entryPoint.depositTo{value: msg.value}(address(this));
        emit Deposited(msg.sender, msg.value);
    }

    /**
     * @notice Withdraw ETH from paymaster's EntryPoint balance
     */
    function withdrawTo(address payable withdrawAddress, uint256 amount) external onlyOwner {
        entryPoint.withdrawTo(withdrawAddress, amount);
        emit Withdrawn(withdrawAddress, amount);
    }

    /**
     * @notice Add stake to EntryPoint (for reputation)
     */
    function addStake(uint32 unstakeDelaySec) external payable onlyOwner {
        entryPoint.addStake{value: msg.value}(unstakeDelaySec);
        emit StakeAdded(msg.value, unstakeDelaySec);
    }

    /**
     * @notice Unlock stake from EntryPoint
     */
    function unlockStake() external onlyOwner {
        entryPoint.unlockStake();
    }

    /**
     * @notice Withdraw unlocked stake
     */
    function withdrawStake(address payable withdrawAddress) external onlyOwner {
        entryPoint.withdrawStake(withdrawAddress);
    }

    // ============================================================================
    // View Functions
    // ============================================================================

    /**
     * @notice Get current paymaster balance in EntryPoint
     */
    function getBalance() external view returns (uint256) {
        return entryPoint.balanceOf(address(this));
    }

    /**
     * @notice Get sponsorship statistics
     */
    function getStats() external view returns (
        uint256 _totalSponsored,
        uint256 _totalCost,
        uint256 _dailySpent,
        uint256 _balance
    ) {
        return (
            totalSponsored,
            totalCost,
            dailySpent,
            entryPoint.balanceOf(address(this))
        );
    }

    /**
     * @notice Check if an address can be sponsored
     */
    function canSponsor(address sender, uint256 estimatedCost) external view returns (bool) {
        // Check balance
        if (entryPoint.balanceOf(address(this)) < estimatedCost) {
            return false;
        }

        // Check whitelist
        if (config.whitelistEnabled && !whitelist[sender]) {
            return false;
        }

        // Check budget
        if (config.budgetEnabled) {
            if (estimatedCost > config.maxCostPerOp) {
                return false;
            }
            if (dailySpent + estimatedCost > config.dailyBudget) {
                return false;
            }
        }

        // Check rate limit
        if (config.rateLimitEnabled) {
            uint256 hoursSinceLastOp = (block.timestamp - lastOpTimestamp[sender]) / 3600;
            if (hoursSinceLastOp < 1 && opsCountInHour[sender] >= config.maxOpsPerHour) {
                return false;
            }
        }

        return true;
    }

    // ============================================================================
    // Fallback
    // ============================================================================

    receive() external payable {
        // Auto-deposit received ETH
        entryPoint.depositTo{value: msg.value}(address(this));
        emit Deposited(msg.sender, msg.value);
    }
}

contracts/ArcSmartAccount.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IEntryPoint} from "./IEntryPoint.sol";

contract ArcSmartAccount {
    error NotOwner();
    error SessionKeyExpired();
    error SessionKeyNotAuthorised();
    error InvalidSignature();
    error InvalidNonce();
    error InvalidCaller();

    event SessionKeyAuthorised(address indexed sessionKey, uint64 expiresAt);
    event SessionKeyRevoked(address indexed sessionKey);
    event Executed(address indexed target, uint256 value, bytes data);

    IEntryPoint public immutable entryPoint;
    address public owner;
    uint256 private userOpNonce;

    struct SessionKey {
        uint64 expiresAt;
        bool exists;
    }

    mapping(address => SessionKey) private sessionKeys;

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyAuthorised() {
        if (msg.sender == owner) {
            _;
            return;
        }
        SessionKey memory key = sessionKeys[msg.sender];
        if (!key.exists) revert SessionKeyNotAuthorised();
        if (key.expiresAt != 0 && block.timestamp > key.expiresAt) revert SessionKeyExpired();
        _;
    }

    constructor(address _entryPoint, address _owner) {
        require(_entryPoint != address(0), "entrypoint required");
        require(_owner != address(0), "owner required");
        entryPoint = IEntryPoint(_entryPoint);
        owner = _owner;
    }

    function getUserOpNonce() external view returns (uint256) {
        return userOpNonce;
    }

    function changeOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "invalid owner");
        owner = newOwner;
    }

    function authorizeSessionKey(address sessionKey, uint64 expiresAt) external onlyOwner {
        require(sessionKey != address(0), "invalid key");
        sessionKeys[sessionKey] = SessionKey({expiresAt: expiresAt, exists: true});
        emit SessionKeyAuthorised(sessionKey, expiresAt);
    }

    function revokeSessionKey(address sessionKey) external onlyOwner {
        if (sessionKeys[sessionKey].exists) {
            delete sessionKeys[sessionKey];
            emit SessionKeyRevoked(sessionKey);
        }
    }

    function isSessionKeyAuthorised(address sessionKey) external view returns (bool authorised, uint64 expiresAt) {
        SessionKey memory key = sessionKeys[sessionKey];
        if (!key.exists) return (false, 0);
        if (key.expiresAt != 0 && block.timestamp > key.expiresAt) return (false, key.expiresAt);
        return (true, key.expiresAt);
    }

    function execute(address target, uint256 value, bytes calldata data) external onlyAuthorised returns (bytes memory result) {
        (bool success, bytes memory returndata) = target.call{value: value}(data);
        require(success, string(returndata));
        emit Executed(target, value, data);
        return returndata;
    }

    function executeBatch(address[] calldata dest, uint256[] calldata value, bytes[] calldata func) external onlyAuthorised {
        require(dest.length == value.length && value.length == func.length, "wrong array lengths");
        for (uint256 i = 0; i < dest.length; i++) {
            (bool success, bytes memory returndata) = dest[i].call{value: value[i]}(func[i]);
            require(success, string(returndata));
            emit Executed(dest[i], value[i], func[i]);
        }
    }

    function validateUserOp(
        IEntryPoint.UserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 missingFunds
    ) external returns (uint256 validationData) {
        if (msg.sender != address(entryPoint)) revert InvalidCaller();
        if (userOp.nonce != userOpNonce) revert InvalidNonce();

        address signer = _recoverSigner(userOpHash, userOp.signature);
        if (signer != owner) {
            SessionKey memory key = sessionKeys[signer];
            if (!key.exists) revert SessionKeyNotAuthorised();
            if (key.expiresAt != 0 && block.timestamp > key.expiresAt) revert SessionKeyExpired();
        }

        unchecked {
            userOpNonce += 1;
        }

        if (missingFunds > 0) {
            (bool success, ) = payable(msg.sender).call{value: missingFunds}("");
            require(success, "missingFunds transfer failed");
        }

        return 0;
    }

    function _recoverSigner(bytes32 hash, bytes memory signature) internal pure returns (address signer) {
        if (signature.length != 65) revert InvalidSignature();
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(signature, 0x20))
            s := mload(add(signature, 0x40))
            v := byte(0, mload(add(signature, 0x60)))
        }
        if (v < 27) {
            v += 27;
        }
        if (v != 27 && v != 28) revert InvalidSignature();
        signer = ecrecover(hash, v, r, s);
        if (signer == address(0)) revert InvalidSignature();
    }

    receive() external payable {}
}

contracts/IEntryPoint.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IEntryPoint {
    struct UserOperation {
        address sender;
        uint256 nonce;
        bytes initCode;
        bytes callData;
        uint256 callGasLimit;
        uint256 verificationGasLimit;
        uint256 preVerificationGas;
        uint256 maxFeePerGas;
        uint256 maxPriorityFeePerGas;
        bytes paymasterAndData;
        bytes signature;
    }

    enum PostOpMode {
        opSucceeded,  // UserOperation succeeded
        opReverted    // UserOperation reverted, paymaster still pays
    }

    function handleOps(UserOperation[] calldata ops, address payable beneficiary) external;

    // Deposit management
    function balanceOf(address account) external view returns (uint256);
    function depositTo(address account) external payable;
    function withdrawTo(address payable withdrawAddress, uint256 withdrawAmount) external;

    // Stake management (for paymasters)
    function addStake(uint32 unstakeDelaySec) external payable;
    function unlockStake() external;
    function withdrawStake(address payable withdrawAddress) external;
}

